let connectionCheck=0;
function connectionBusy(busy){$('create-room').disabled=busy;$('join-room').disabled=busy;$('check-server').disabled=busy;}
function connectionError(error){$('connect-message').textContent=error.message;}
async function checkConnection(force=false){
 const attempt=++connectionCheck;connectionBusy(true);$('server-status').textContent='공통 서버 연결 확인 중…';
 const status=await client.checkServer({force});
 if(attempt!==connectionCheck||!$('connect-dialog').open)return;
 $('server-status').textContent=status.message;$('server-status').dataset.status=status.kind;
 $('create-room').disabled=!status.ready;$('join-room').disabled=!status.ready;$('check-server').disabled=false;
}
$('open-connect').onclick=()=>{$('room-code').value=client.code??'';$('join-role').value=client.role==='biology'?'biology':'engineering';$('connect-message').textContent=client.mode==='shared'?`현재 실험실 ${client.code} · ${client.role==='biology'?'생명과학':'산업공학'} 역할. 코드를 다른 태블릿에 입력하세요.`:'단독 연구는 이 기기에 저장됩니다. 공통 서버가 확인되어야 두 태블릿이 같은 실험에 참여할 수 있습니다.';$('leave-room').textContent=client.mode==='shared'?'공유 실험 나가기 · 새 단독 연구':'단독 연구 계속하기';$('connect-dialog').showModal();checkConnection();};
$('check-server').onclick=()=>checkConnection(true);
$('open-tools').onclick=()=>$('tools-dialog').showModal();qa('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('create-room').onclick=async()=>{connectionBusy(true);try{await client.create($('join-role').value);$('connect-dialog').close();notice('실험실 '+client.code+' 생성. 다른 태블릿에 같은 코드를 입력하세요.');}catch(e){connectionError(e);await checkConnection(true);}};
$('join-room').onclick=async()=>{connectionBusy(true);try{await client.joinAvailable($('room-code').value.trim().toUpperCase(),$('join-role').value);$('connect-dialog').close();}catch(e){connectionError(e);await checkConnection();}};
$('leave-room').onclick=()=>{if(client.mode==='shared')client.leave();$('connect-dialog').close();};
$('save-world').onclick=()=>{exportMode='state';perform('export');};client.addEventListener('export',e=>{if(exportMode==='inventory'){download('BLOODFLOW_inventory.csv',csv(e.detail.snapshot.units.filter(u=>['ready','queue','truck','review'].includes(u.status)).map(u=>({id:u.id,kind:u.kind,bloodType:u.bloodType,status:u.status,node:u.node,createdHours:u.created,expiryHours:u.expiry,temperature:u.temperature,syntheticTemperature:true,review:u.review,reviewReason:u.reviewReason}))),'text/csv;charset=utf-8');exportMode='state';}else download('BLOODFLOW_state.json',JSON.stringify(e.detail));});
$('load-world').onclick=()=>{if(lastState.running)return notice('일시정지한 뒤 복원하세요.');$('state-file').click();};
$('state-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>24*1024*1024)throw Error('파일이 24MB를 초과합니다.');const raw=JSON.parse(await file.text());perform('restore',{snapshot:raw.snapshot??raw,notes:raw.notes,result:raw.result});}catch(e){notice('상태 파일을 복원하지 못했습니다: '+e.message);}finally{$('state-file').value='';}};
$('inventory-csv').onclick=()=>{exportMode='inventory';perform('export');};
$('logs-json').onclick=()=>download('BLOODFLOW_events.json',JSON.stringify(lastState.logs,null,2));
$('print-studio').onclick=()=>{$('tools-dialog').close();navigate('research');setTimeout(()=>window.print(),150);};$('demo-open').onclick=()=>{$('tools-dialog').close();openDemo();};
function openDemo(){const national=lastState.world.c.network==='nationwide';$('demo-dialog').querySelector('h2').textContent=national?'3분 · 전국의 부족과 재배치':'3분 · 같은 위기, 다른 정책';$('demo-dialog').querySelector('.project-title').textContent=national?'가상 1~3일에 서울·경기·인천 연구권역 수요가 3배가 됩니다. 공급 정책을 선택하고 공동 세계의 제제·운송을 관찰하세요.':'가상 1일째부터 인하대병원의 수요가 3배로 늘어납니다. 안전재고 정책을 선택하세요.';
 const row=$('demo-dialog').querySelector('.btn-row');row.innerHTML=national?Object.entries(NATIONAL_POLICIES).map(([key,name])=>`<button data-demo="${key}" ${key==='C'?'class="primary"':''}>${key} · ${name}</button>`).join(''):'<button data-demo="1">안전재고 1일</button><button data-demo="6" class="primary">안전재고 6일</button>';
 qa('[data-demo]',row).forEach(b=>b.onclick=()=>startDemo(b.dataset.demo));$('demo-dialog').showModal();
}
function startDemo(choice){
 if(client.mode==='shared'&&client.role!=='engineering')return notice('공통 세계의 위기 체험은 산업공학 역할에서 시작하세요. Biology도 독립 COMPUTE를 실행할 수 있습니다.');
 const national=lastState.world.c.network==='nationwide',patch={seed:20261021,scenario:'crisis',...(national?{redistribution:choice}:{safetyDays:Number(choice)})};
 if(!perform('configure',{patch}))return;
 demo={policy:choice,national,started:Date.now(),duration:180};$('demo-dialog').close();navigate(national?'nationwide':'engineering');perform('clock',{mode:'TIMELAPSE',speed:24,running:true});clearInterval(demoTimer);demoTimer=setInterval(()=>{renderDemo();if(Date.now()-demo.started>=180000)finishDemo();},1000);renderDemo();
}
function renderDemo(){if(!demo)return;const remaining=Math.max(0,demo.duration-Math.floor((Date.now()-demo.started)/1000)),stage=lastState.world.t<24?'① 위기 전 · 공급과 재고 관찰':lastState.world.t<72?'② 수요 3배 · 부족·운송·적합성 관찰':'③ 같은 조건으로 정책 비교';$('demo-banner').classList.remove('hidden');$('demo-banner').innerHTML=`<div><h2>${stage}</h2><p>${demo.national?'서울·경기·인천 · 가상 수요 급증 · 정책 '+demo.policy:'인하대병원 · 가상 수요 급증 · 안전재고 '+demo.policy+'일'} · 시드 20261021</p></div><div class="countdown">${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}</div><div class="btn-row"><button id="finish-demo" class="small">지금 정책 결과 비교</button><button id="close-demo" class="quiet small">체험 종료</button></div>`;$('finish-demo').onclick=finishDemo;$('close-demo').onclick=()=>{clearInterval(demoTimer);demo=null;$('demo-banner').classList.add('hidden');perform('clock',{mode:'TIMELAPSE',speed:24,running:false});};}
function finishDemo(){clearInterval(demoTimer);if(!demo)return;const national=demo.national;demo=null;$('demo-banner').classList.add('hidden');perform('clock',{mode:'TIMELAPSE',speed:24,running:false});perform('compute',{plan:{experiment:national?'N':'A',control:1,treatment:6,days:3,repeats:2,seed:20261021}});currentExperiment=national?'N':'A';navigate('research');notice('같은 위기·생명과학 조건과 시드로 정책 결과를 계산합니다. 결과는 미리 정하지 않습니다.');}
client.addEventListener('ack',e=>{if(e.detail?.type==='notes')for(const [key,value] of Object.entries(e.detail.patch))if(draftNotes.get(key)===value)draftNotes.delete(key);});
client.addEventListener('change',refresh);client.addEventListener('notice',e=>notice(e.detail));client.addEventListener('saved',()=>{$('save-status').textContent='저장됨';});
navigate(currentLab,true);requestAnimationFrame(animateMap);await client.restoreAutosave();
if(!singleFile&&location.protocol!=='file:'&&location.hostname!=='terminal.local'&&'serviceWorker' in navigator)navigator.serviceWorker.register('/bloodflow/sw.js',{scope:'/bloodflow/'}).catch(()=>{});
